#define BTN_MID_PIN     33
#define BTN_RIGHT_PIN   13
#define OLED_SDA_PIN    21
#define OLED_SCL_PIN    22

// --- OLED CONFIG ---
#define I2C_MASTER_NUM 0
#define I2C_MASTER_FREQ_HZ 100000 
#define OLED_ADDR 0x3C

// --- EVENTS ---
typedef enum {
    EV_LEFT_CLICK,
    EV_RIGHT_CLICK,
    EV_MID_CLICK,
    EV_MID_DCLICK
} app_event_t;

